def ssh_target(host):
    """Real hostname and port for an SSH address (follows ~/.ssh/config)."""
    try:
        out = subprocess.run(["ssh", "-G", host], capture_output=True, text=True, timeout=5).stdout
        conf = dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
        return conf.get("hostname", host), int(conf.get("port", 22))
    except (OSError, ValueError, subprocess.SubprocessError):
        return host.rsplit("@", 1)[-1], 22


def server_up(host):
    try:
        socket.create_connection(ssh_target(host), timeout=2).close()
        return True
    except OSError:
        return False


def wake_on_lan(mac):
    mac = re.sub(r"[^0-9a-fA-F]", "", mac)
    if len(mac) != 12:
        return
    packet = b"\xff" * 6 + bytes.fromhex(mac) * 16
    addrs = {"255.255.255.255"}
    try:  # the local networks' own broadcast addresses work more reliably
        out = subprocess.run(["ip", "-o", "-4", "addr", "show"], capture_output=True, text=True).stdout
        addrs |= set(re.findall(r"brd (\d+\.\d+\.\d+\.\d+)", out))
    except OSError:
        pass
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
    for addr in addrs:
        try:
            s.sendto(packet, (addr, 9))
        except OSError:
            pass


